mapper.select:
select *
from agent_memory
where enabled = 1
  and agent_code = #{agentCode}
  and symbol = #{symbol}
order by

  (

      case when lower(event_tags_json) like lower(concat(concat('%"', #{tag}), '"%')) then 1 else 0 end

  ) desc,

quality_score desc, updated_at desc, id desc
limit #{limit}
